function enhance(root){window.WTControls?.enhance(root)}
function modal(title,body,footer='',kind='drawer'){
 const d=document.createElement('dialog');d.className='ex-overlay '+(kind==='drawer'?'ex-drawer':kind==='wide'?'wide':kind==='small'?'':'medium');d.setAttribute('aria-label',title);
 d.innerHTML=`<header class="ex-overlay-header"><h2>${title}</h2><button class="ex-close" data-action="close" aria-label="关闭">×</button></header><div class="ex-overlay-body">${body}</div>${footer?`<footer class="ex-overlay-footer">${footer}</footer>`:''}`;
 $('#layers').append(d);d.addEventListener('close',()=>{d.remove();syncLayers()});d.showModal();d.addEventListener('cancel',e=>{if(d.dataset.processing==='true'||d.dataset.dirty==='true'){e.preventDefault();if(d.dataset.dirty==='true')close(d)}});syncLayers();enhance(d);return d;
}
function syncLayers(){const all=[...document.querySelectorAll('dialog[open]')];all.forEach((d,i)=>d.classList.toggle('ex-underlay',i<all.length-1))}
function close(d){if(!d)return;if(d.dataset.dirty==='true'){confirm('放弃未保存的修改？','关闭后本次修改不会保存。',()=>{d.dataset.dirty='false';d.close()});return}d.close()}
function message(msg,error=false){const top=[...document.querySelectorAll('dialog')].at(-1);const target=top?document.createElement('div'):$('#toast');target.textContent=msg;target.hidden=false;target.dataset.error=String(error);if(top){target.className='ex-notice '+(error?'danger':'success');target.setAttribute('role','status');$('.ex-overlay-body',top).prepend(target)}else{clearTimeout(message.timer);message.timer=setTimeout(()=>target.hidden=true,4500)}}
function details(items){return `<div class="ex-description-container"><dl class="ex-description-list" data-density="dense">${items.map(([k,v])=>`<div class="ex-desc-item"><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></div>`}
const section=(title,body)=>`<section class="detail-block"><h3 class="ex-section-title detail">${title}</h3>${body}</section>`;
