 const body=`${review?`<div class="ex-notice info">待处理队列 · 当前 ${r.id} · 剩余 ${contents.filter(c=>c.status==='pending').length} 条</div>`:''}<div class="detail-lead">${r.noCover?'<span class="cover no-cover">暂无<br>封面</span>':cover(r.id%8)}<div><h3>${esc(r.title)}</h3>${status(r.status)}<p>抖音 · ${r.author} · ${r.category}</p></div></div>${section('内容信息',details([['内容 ID',r.id],['运营团队',r.team||'游戏运营一组'],['浏览量',(r.likes*8).toLocaleString()],['点赞 / 收藏',`${r.likes.toLocaleString()} / ${r.favorite.toLocaleString()}`],['发布时间',`2026-11-0${r.day} 08:32:16`],['入库时间','2026-11-05 09:04:32']]))}${section('来源追溯',details([['来源方式',r.source==='strategy'?'挖掘策略':r.source==='link'?'ID/链接发现':'关键词发现'],['来源',r.source==='strategy'?textButton(strategies.find(s=>s.id===r.strategy)?.name,'source',`data-id="${id}"`):'人工'],['外部可访问性','未知（演示未连接外部平台）']]))}${r.material?section('关联素材',textButton(`素材 ${r.material} · ${esc(r.title)}`,'material-info',`data-id="${id}"`)+ '<p class="ex-help">所属团队：游戏运营一组。已转素材不代表已完成内容生产。</p>'):''}<div class="ex-notice">封面仅为示意。本原型没有真实视频播放或外部可访问性检查。</div>`;
 const d=modal(review?'内容审核':'内容详情',body,review?button('跳过','review-skip')+button('忽略并下一条','review-ignore')+button('转素材并下一条','review-material','primary'):r.status==='pending'?button('忽略','ignore','',`data-id="${id}"`)+button('转素材','material','primary',`data-id="${id}"`):r.status==='ignored'?button('恢复','restore','primary',`data-id="${id}"`):'');d.dataset.contentId=id;
