function sourceDetail(id){const r=contents.find(c=>c.id===id);const s=strategies.find(s=>s.id===r.strategy),t=tasks.find(t=>t.id===r.taskId);modal('来源详情',section('来源策略',details([['策略 ID',s.id],['策略名称',esc(s.name)],['策略类型','关键词'],['执行周期',s.schedule],['挖掘关键词',esc(s.keywords)]]))+section('当次任务',details([['任务 ID',t?.id||'—'],['触发方式',t?.trigger||'定时触发'],['任务状态',status(t?.status||'pending',true)],['创建时间','2026-11-05 09:00:00'],['完成时间',t&&['pending','running'].includes(t.status)?'—':'2026-11-05 09:04:32']]))+'<p class="ex-help">策略配置与执行快照分别保留，后续编辑不会改写历史任务。</p>',textButton('前往策略页面','goto-strategy',`data-id="${s.id}"`)+button('前往任务页面','strategy-tasks','primary',`data-id="${s.id}"`))}
function strategyDetail(id){const s=strategies.find(s=>s.id===id);if(!s){modal('来源策略不可用','<p>当前策略已删除或无法读取。历史任务与当次快照仍保留。</p>',button('关闭','close'),'small');return}modal('策略详情',section(esc(s.name),details([['策略 ID',s.id],['所属类目',s.category],['运营团队','游戏运营一组'],['平台','抖音'],['状态',s.enabled?'启用':'停用'],['执行周期',s.schedule],['关键词',esc(s.keywords)],['时区','Asia/Shanghai']]))+section('转素材规则',`<p>${esc(ruleSummary(s.rules))}</p><p class="ex-help">从上往下判断，第一条命中的规则决定是否转素材；未命中留在内容池。</p>`)+section('最近执行',textButton('查看执行记录','strategy-tasks',`data-id="${id}"`)),manage()?button('编辑策略','edit','primary',`data-id="${id}"`):'')}
function taskDetail(id){const t=tasks.find(t=>t.id===id),s=strategies.find(s=>s.id===t.strategy);const d=modal('挖掘任务详情',`<div class="summary-line"><div><h3>${esc(t.name)}</h3><span class="mono">任务 ID ${id}</span></div>${status(t.status,true)}</div><div class="task-counts">${[['发现',t.found],['新增',t.added],['自动素材',t.auto],['待审核',t.pending],['失败（关键词）',t.failed]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>${t.failed?`<div class="ex-notice danger">${t.failed} 个关键词查询失败：供应方请求超时。已成功入池结果保留，可仅重试失败项。</div>`:''}${section('任务与执行快照',details([['任务来源',t.strategy?textButton(esc(s?.name||t.strategyName||'来源策略'),'strategy-detail',`data-id="${t.strategy}"`):esc(t.strategyName)],['运营团队','游戏运营一组'],['所属类目',t.category||s?.category||'—'],['触发方式',t.parent?'失败项重试':t.trigger||'定时触发'],['父任务',t.parent||'—'],['扫描 / 重复',t.found?`${t.found} / ${t.found-t.added}`:'—'],['计划时间','2026-11-05 09:00:00'],['当次关键词',esc(t.snapshot?.keywords||'快照缺失')],['当次执行周期',t.snapshot?.schedule||'快照缺失'],['当次转素材规则',t.snapshot?.rules?esc(ruleSummary(t.snapshot.rules)):'快照缺失']]))}${section('执行记录',`<table class="mini-table"><thead><tr><th>时间</th><th>阶段</th><th>结果</th></tr></thead><tbody><tr><td>09:00:00</td><td>创建任务</td><td>当次配置快照已保存</td></tr>${!['pending'].includes(t.status)?`<tr><td>09:00:02</td><td>关键词发现</td><td>${t.failed?'部分查询超时':'读取候选结果'}</td></tr>`:''}${t.status==='success'||t.status==='partial_success'?`<tr><td>09:04:32</td><td>内容入池</td><td>新增 ${t.added} 条，自动素材 ${t.auto} 条，待审核 ${t.pending} 条</td></tr>`:''}</tbody></table>`)}<p class="ex-help">发现、新增、自动素材与待审核存在包含关系，不相加为总量；关键词失败与作品数量分开计数。此处均为演示数据。</p>`,manage()&&t.failed?button('重试失败项','retry','primary',`data-id="${id}"`):'');d.dataset.taskId=id}
