let editRules=[];
function editor(id){if(!manage())return;const s=strategies.find(s=>s.id===id);editRules=JSON.parse(JSON.stringify(s?.rules||[]));
 const d=modal(s?'编辑挖掘策略':'新增挖掘策略',`<form id="strategy-form" class="ex-form-container"><section class="ex-section"><h3 class="ex-section-title form">基础信息</h3><div class="ex-form-grid">${input('策略名称','strategy-name','例如：王者高赞内容发现',s?.name||'','required full')}${role==='admin'?select('运营团队','strategy-team',['游戏运营一组'],'游戏运营一组',false):''}${select('所属类目','strategy-category',['王者荣耀','原神','和平精英'],s?.category||'',true)}${field('平台','strategy-platform','<input id="strategy-platform" value="抖音" readonly>')}${input('挖掘关键词','strategy-keywords','多个关键词用逗号分隔',s?.keywords||'','required full')}<p class="ex-help full">关键词用于发现候选内容；博主发现暂未开放。</p></div></section><section class="ex-section"><h3 class="ex-section-title form">执行计划</h3><div class="ex-form-grid">${select('执行周期','schedule-mode',[['manual','手动执行'],['daily','每天固定时间'],['interval','按分钟间隔']],s?.schedule.startsWith('每天')?'daily':s?.schedule.startsWith('每 ')?'interval':'manual',false)}<div id="schedule-value"></div>${select('策略状态','strategy-enabled',[['disabled','停用'],['enabled','启用']],s?.enabled?'enabled':'disabled',false)}</div><p class="rules-help">时区 Asia/Shanghai。启用不会立即执行；停用不打断在途任务，修改仅影响后续任务。</p></section><section class="ex-section"><h3 class="ex-section-title form">转素材规则</h3><p class="rules-help">按优先级从上往下判断，第一条命中即决定结果。“命中”转为素材，“过滤”留在内容池；不配置规则则只入池。</p><div id="rules"></div>${button('＋ 添加优先级','add-rule')}<p id="strategy-error" class="field-error" role="alert"></p></section></form>`,button('取消','close')+button('保存','save-strategy','primary'));
 d.dataset.editId=id||'';$('#strategy-name',d).required=true;$('#strategy-keywords',d).required=true;$('#strategy-category',d).required=true;drawSchedule(d);if(s?.schedule.startsWith('每天'))$('#schedule-time',d).value=s.schedule.slice(3);if(s?.schedule.startsWith('每 '))$('#schedule-minutes',d).value=s.schedule.split(' ')[1];drawRules(d)
}
function drawSchedule(d){const mode=$('#schedule-mode',d).value;$('#schedule-value',d).innerHTML=mode==='daily'?field('执行时间','schedule-time','<input type="time" id="schedule-time" value="09:00" required>'):mode==='interval'?field('间隔分钟','schedule-minutes','<input type="number" id="schedule-minutes" min="1" step="1" value="60" required>'):''}
function drawRules(d){
 $('#rules',d).innerHTML=editRules.map((r,i)=>`<div class="rule-card"><div class="rule-head"><strong><span class="rule-index">${i+1}</span>优先级 ${i+1}</strong><div class="ex-actions"><button type="button" class="icon-button" data-action="rule-up" data-index="${i}" aria-label="上移优先级 ${i+1}" title="上移" ${i===0?'disabled':''}>${icon('up',16)}</button><button type="button" class="icon-button" data-action="rule-down" data-index="${i}" aria-label="下移优先级 ${i+1}" title="下移" ${i===editRules.length-1?'disabled':''}>${icon('down',16)}</button><button type="button" class="icon-button" data-action="rule-delete" data-index="${i}" aria-label="删除优先级 ${i+1}" title="删除规则">${icon('trash',16)}</button></div></div><div class="ex-form-grid">${select('规则类型',`action-${i}`,[['match','命中 → 自动转素材'],['filter','过滤 → 留在内容池']],r.action,false)}${select('判断方式',`logic-${i}`,[['all','全部满足'],['any','任一满足']],r.logic,false)}</div>${r.conditions.map((c,j)=>`<div class="rule-condition" data-rule="${i}" data-condition="${j}">${select('字段',`field-${i}-${j}`,[['published_at','发布时间'],['like_count','点赞量'],['favorite_count','收藏量']],c.field,false)}${select('运算符',`op-${i}-${j}`,c.field==='published_at'?[['recent_days','近 N 天'],['recent_hours','近 N 小时'],['gte','不早于'],['lt','早于']]:[['gte','大于等于'],['lte','小于等于'],['eq','等于']],c.op,false)}${field('条件值',`value-${i}-${j}`,`<input id="value-${i}-${j}" type="${c.field==='published_at'&&['gte','lt'].includes(c.op)?'datetime-local':'number'}" value="${esc(c.value)}" min="${c.field==='published_at'?1:0}" step="1" required aria-label="优先级 ${i+1} 条件 ${j+1} 的值">`)}<button type="button" class="icon-button" data-action="condition-delete" data-index="${i}" data-condition="${j}" aria-label="删除优先级 ${i+1} 的条件 ${j+1}" title="删除条件" ${r.conditions.length===1?'disabled':''}>${icon('trash',16)}</button></div>`).join('')}${textButton('＋ 添加条件','condition-add',`data-index="${i}"`)}</div>`).join('');
 $('#rules',d).querySelectorAll('.rule-condition').forEach(row=>{if(Number(row.dataset.condition)>0)row.querySelectorAll('.ex-field>label').forEach(label=>label.classList.add('visually-hidden'))});enhance($('#rules',d));
}
function syncRules(d){editRules.forEach((r,i)=>{r.action=$(`#action-${i}`,d).value;r.logic=$(`#logic-${i}`,d).value;r.conditions.forEach((c,j)=>{c.field=$(`#field-${i}-${j}`,d).value;c.op=$(`#op-${i}-${j}`,d).value;c.value=$(`#value-${i}-${j}`,d).value})})}
function saveStrategy(d){if(demoFlags.saveFailure){$('#strategy-error',d).textContent='策略未保存，请稍后重试。输入与规则已保留。';$('#strategy-error',d).scrollIntoView({block:'nearest'});return}syncRules(d);const f=$('#strategy-form',d);if(!f.reportValidity())return;const fail=msg=>{$('#strategy-error',d).textContent=msg;$('#strategy-error',d).scrollIntoView({block:'nearest'})};if(editRules.length&&!editRules.some(r=>r.action==='match'))return fail('非空规则组至少需要一条“命中”规则。');for(const r of editRules)for(const c of r.conditions)if(c.field==='published_at'&&['recent_days','recent_hours'].includes(c.op)&&(Number(c.value)> (c.op==='recent_days'?365:8760)||Number(c.value)<1||!Number.isInteger(Number(c.value))))return fail('相对发布时间须为整数：1–365 天或 1–8760 小时。');let s=strategies.find(s=>s.id===Number(d.dataset.editId));const mode=$('#schedule-mode',d).value;const payload={name:$('#strategy-name',d).value.trim(),keywords:$('#strategy-keywords',d).value.trim(),category:$('#strategy-category',d).value,enabled:$('#strategy-enabled',d).value==='enabled',schedule:mode==='daily'?`每天 ${$('#schedule-time',d).value}`:mode==='interval'?`每 ${$('#schedule-minutes',d).value} 分钟`:'手动执行',rules:JSON.parse(JSON.stringify(editRules))};if(!payload.name||!payload.keywords)return fail('请输入策略名称和关键词。');if(s)Object.assign(s,payload);else strategies.unshift({id:Math.max(...strategies.map(s=>s.id))+1,...payload});d.dataset.dirty='false';close(d);drawTable();message('策略已保存')}
function discover(mode){const menu=$('#discover-menu');if(menu?.matches(':popover-open'))menu.hidePopover();const d=modal(mode==='id'?'ID / 链接发现':'关键词发现',`<div class="ex-form-container"><div class="ex-form-grid">${role==='admin'?select('运营团队','import-team',['游戏运营一组'],'游戏运营一组',false):''}${select('所属类目','import-category',['王者荣耀','原神','和平精英'],'',true)}${field('平台','import-platform','<input id="import-platform" readonly value="抖音">')}${mode==='id'?field('视频 ID / 分享链接','discover-query','<textarea id="discover-query" placeholder="每行一个视频 ID 或抖音分享链接，最多 100 个目标"></textarea>','full required'):input('关键词','discover-query','输入关键词，如：王者荣耀 上分','','full required')}</div><p class="rules-help">先搜索并选择结果，再加入内容池；未选择的结果不会写入。${mode==='id'?'每 10 个目标分批处理。':'默认搜索 20 条，可继续加载结果。'}</p>${button('搜索','search-discovery','primary')}<p id="discover-error" class="field-error" role="alert"></p><div id="discovery-results"></div></div>`,button('取消','close')+button('加入内容池','import','primary','disabled'),'wide');d.dataset.mode=mode}
function searchDiscovery(d){const value=$('#discover-query',d).value.trim();if(!value){$('#discover-error',d).textContent='请先输入搜索内容。';return}if(d.dataset.mode==='id'&&value.split('\n').filter(s=>s.trim()).length>100){$('#discover-error',d).textContent='单批最多 100 个目标，请拆分后重试。';return}$('#discover-error',d).textContent='';$('#discovery-results',d).innerHTML=`<div class="rule-head" style="margin-top:24px"><h3>搜索结果 · 3 条（演示）</h3><span class="ex-help">已入池内容会去重</span></div><table class="mini-table"><thead><tr><th>选择</th><th>内容</th><th>作者</th><th>互动</th></tr></thead><tbody>${[0,1,2].map(i=>`<tr><td><input type="checkbox" data-result="${i}" aria-label="选择搜索结果 ${i+1}"></td><td>${esc(candidateTitles[i])}</td><td>${contents[i].author}</td><td>赞 ${contents[i].likes.toLocaleString()}</td></tr>`).join('')}</tbody></table><p class="ex-help">演示结果仅用于核对选择与入池流程；不代表真实搜索结果。</p>`}
function batch(action,ids){const list=contents.filter(c=>ids.includes(c.id));const required=action==='restore'?'ignored':'pending';const eligible=list.filter(c=>c.status===required);let complete=false;const d=modal(action==='material'?'批量转素材':action==='ignore'?'批量忽略':'批量恢复',`<div class="summary-line"><div><strong>${list.length}</strong> 项待核对</div><span class="tag info">等待确认</span></div><p class="rules-help">符合条件 ${eligible.length} 项；其余 ${list.length-eligible.length} 项将跳过。逐项独立处理，成功项保留。</p><div id="batch-result"><table class="mini-table"><thead><tr><th>内容 ID</th><th>内容</th><th>处理结果</th></tr></thead><tbody>${list.map(c=>`<tr data-batch-id="${c.id}"><td>${c.id}</td><td>${esc(c.title)}</td><td>${c.status===required?'等待处理':'状态不适用，将跳过'}</td></tr>`).join('')}</tbody></table></div>`,button('取消','close')+button('开始本地演示','batch-start','primary'),'wide');d.batch={action,list,eligible};d.addEventListener('cancel',e=>{if(d.dataset.processing==='true')e.preventDefault()});d.finish=partial=>{const failed=partial?eligible.at(-1):null;eligible.forEach(c=>{if(c!==failed)applyContent(c,action)});const success=eligible.length-(failed?1:0);$('#batch-result',d).innerHTML=`<div class="ex-notice ${failed?'warning':'success'}">演示结果：成功 ${success} 项 · 失败 ${failed?1:0} 项 · 跳过 ${list.length-eligible.length} 项${action==='material'?`。素材去向：游戏运营一组 ${success} 条。`:''}</div><table class="mini-table"><thead><tr><th>ID</th><th>内容</th><th>结果</th></tr></thead><tbody>${list.map(c=>`<tr><td>${c.id}</td><td>${esc(c.title)}</td><td>${c===failed?'演示：转素材失败，可重试':eligible.includes(c)?'成功':'已跳过'}</td></tr>`).join('')}</tbody></table>`;d.dataset.processing='false';$('.ex-close',d).disabled=false;$('.ex-overlay-footer',d).innerHTML=(failed?button('仅重试失败项','batch-retry','primary'):'')+button('完成','close');d.failed=failed;complete=true;selection.clear();drawTable()};d.addEventListener('close',()=>{if(complete)drawTable()})}
function applyContent(r,action){delete r.lastError;if(action==='material'){r.status='material_created';r.material=6000+r.id}else r.status=action==='ignore'?'ignored':'pending'}
function reviewNext(skip=false){const candidates=contents.filter(c=>c.status==='pending');if(skip&&candidates.length>1)candidates.push(candidates.shift());if(candidates.length)contentDetail(candidates[0].id,true);else message('当前待处理队列已完成（演示）。')}
function confirm(title,body,fn){const d=modal(title,`<p>${body}</p>`,button('取消','close')+button('确认','confirm','primary'),'small');d.confirm=fn}
function goTasks(id){saveView();document.querySelectorAll('dialog').forEach(d=>close(d));page='tasks';history.replaceState(null,'','#tasks');filters={};selection.clear();routeStrategy=id;currentPage=1;render()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=Number(b.dataset.id),d=b.closest('dialog');const r=contents.find(c=>c.id===id);switch(a){
 case 'collapse-nav':document.body.classList.toggle('nav-expanded');break;
 case 'columns':{const menu=$('#column-settings'),rect=b.getBoundingClientRect();menu.style.top=rect.bottom+8+'px';menu.style.left=Math.max(12,Math.min(rect.right-240,innerWidth-252))+'px';break}
 case 'reset-columns':displayFields=new Set(['category','metrics','source','status','published']);drawColumnSettings();drawTable();$('#column-settings').hidePopover();$('[data-action="columns"]')?.focus();break;
 case 'sort':sortState={key:b.dataset.key,direction:sortState.key===b.dataset.key&&sortState.direction==='desc'?'asc':'desc'};drawTable();break;
 case 'discover':{const menu=$('#discover-menu'),r=b.getBoundingClientRect();menu.style.top=(r.bottom+6)+'px';menu.style.right=Math.max(12,innerWidth-r.right)+'px';break}
 case 'close':if(d?.dataset.processing!=='true')close(d);break;
 case 'reload':scene='normal';$('#scene').value=scene;render();break;
 case 'reset':filters={};scene='normal';$('#scene').value=scene;selection.clear();render();break;
 case 'unselect':selection.clear();drawTable();break;
 case 'prev':currentPage--;drawTable();break;case 'next':currentPage++;drawTable();break;
 case 'clear-route':routeStrategy=null;render();break;
 case 'detail':contentDetail(id);break;case 'source':sourceDetail(id);break;
 case 'material':case 'ignore':case 'restore':if(r){if(a==='material'&&demoFlags.actionFailure){r.lastError='素材创建失败，请稍后重试';drawTable();message(r.lastError,true);return}applyContent(r,a);if(d)close(d);drawTable();message(a==='material'?`演示：素材 ${r.material}「${r.title}」已加入${r.team||'游戏运营一组'}。`:a==='ignore'?'已忽略该内容（演示）。':'已恢复为待处理（演示）。')}break;
 case 'material-info':modal('关联素材',details([['素材 ID',r.material],['素材名称',esc(r.title)],['所属团队','游戏运营一组'],['来源内容',r.id]])+'<p class="rules-help">素材后续的准备、制作与使用在内容生产模块完成。</p>','','small');break;
 case 'batch-material':case 'batch-ignore':case 'batch-restore':batch(a.slice(6),[...selection]);break;
 case 'batch-start':d.dataset.processing='true';$('.ex-close',d).disabled=true;$('.ex-overlay-footer',d).innerHTML='<span class="ex-help">处理中不能关闭。请用演示控制手动给出结果。</span>';$('.ex-overlay-body',d).insertAdjacentHTML('beforeend',`<div class="batch-controls">仅用于评审的演示控制${button('演示全部成功','batch-success')}${button('演示部分失败','batch-partial','',d.batch.action==='material'&&d.batch.eligible.length>1?'':'disabled')}</div>`);break;
 case 'batch-success':case 'batch-partial':d.finish(a==='batch-partial');break;
 case 'batch-retry':{const failed=d.failed;close(d);batch('material',[failed.id]);break}
 case 'discover-id':discover('id');break;case 'discover-keyword':discover('keyword');break;
 case 'search-discovery':searchDiscovery(d);break;
 case 'import':{if(!$('#import-category',d).value){$('#discover-error',d).textContent='请选择所属类目。';return}const results=[...d.querySelectorAll('[data-result]:checked')];if(!results.length)return;const max=Math.max(...contents.map(c=>c.id));let added=0;results.forEach((el,i)=>{const n=Number(el.dataset.result);if(importedCandidates.has(n))return;importedCandidates.add(n);contents.unshift({...contents.find(c=>c.id===8201+n),title:candidateTitles[n],id:max+i+1,category:$('#import-category',d).value,source:d.dataset.mode==='id'?'link':'search',status:'pending',material:null});added++});close(d);scene='normal';drawTable();message(`演示：新增 ${added} 条，重复 ${results.length-added} 条；尚未生成素材。`);break}
 case 'review':reviewSession=null;if(!filtered().some(c=>c.status==='pending'))message('当前筛选范围内没有待处理内容。');else contentDetail(filtered().find(c=>c.status==='pending').id,true);break;
 case 'review-skip':case 'review-ignore':case 'review-material':advanceReview(a,d);break;
 case 'strategy-detail':strategyDetail(id);break;case 'strategy-tasks':goTasks(id);break;
 case 'goto-strategy':saveView();document.querySelectorAll('dialog').forEach(x=>close(x));page='strategies';history.replaceState(null,'','#strategies');filters={search:String(id)};render();break;
 case 'task-detail':taskDetail(id);break;case 'create':editor();break;case 'edit':editor(id);break;
 case 'save-strategy':saveStrategy(d);break;
 case 'add-rule':syncRules(d);editRules.push({action:'match',logic:'all',conditions:[{field:'like_count',op:'gte',value:5000}]});drawRules(d);break;
 case 'rule-up':case 'rule-down':case 'rule-delete':case 'condition-add':case 'condition-delete':{syncRules(d);const i=Number(b.dataset.index),j=Number(b.dataset.condition);if(a==='rule-delete')editRules.splice(i,1);else if(a==='condition-add')editRules[i].conditions.push({field:'like_count',op:'gte',value:5000});else if(a==='condition-delete')editRules[i].conditions.splice(j,1);else{const n=i+(a==='rule-up'?-1:1);[editRules[i],editRules[n]]=[editRules[n],editRules[i]]}drawRules(d);break}
 case 'toggle':{const s=strategies.find(s=>s.id===id);confirm(s.enabled?'停用策略':'启用策略',s.enabled?'停用后不再创建周期任务，在途任务仍按原快照完成。':'启用后等待下一个计划窗口，不会立即执行。',()=>{s.enabled=!s.enabled;drawTable();message('策略状态已在本地更新（演示）。')});break}
 case 'run':confirm('执行挖掘策略','本次将在本地新增一个待执行演示任务；正式产品仍须核对启用状态及同策略在途任务。',()=>{if(tasks.some(t=>t.strategy===id&&['pending','running'].includes(t.status)))return message('该策略已有待执行或执行中任务。');tasks.unshift({id:Math.max(...tasks.map(t=>t.id))+1,name:'手动执行 · 演示任务',strategy:id,trigger:'手动触发',snapshot:{keywords:strategies.find(s=>s.id===id).keywords,schedule:strategies.find(s=>s.id===id).schedule,rules:JSON.parse(JSON.stringify(strategies.find(s=>s.id===id).rules))},status:'pending',found:0,added:0,auto:0,pending:0,failed:0});drawTable();message('已创建待执行演示任务，尚未执行。')});break;
 case 'retry':{if(!manage())return;if(demoFlags.retryFailure){message('任务未受理，请稍后重试。原任务与失败项保持不变。',true);return}const t=tasks.find(t=>t.id===id);confirm('仅重试失败项',`原任务 ${id} 的状态与统计保持不变。新任务仅包含失败关键词，不重复处理成功结果。`,()=>{if(tasks.some(n=>n.strategy===t.strategy&&['pending','running'].includes(n.status)))return message('该策略已有在途任务，请等待结束后再重试。');tasks.unshift({id:Math.max(...tasks.map(t=>t.id))+1,name:'失败项重试 · 演示任务',strategy:t.strategy,parent:id,snapshot:{...t.snapshot},status:'pending',found:0,added:0,auto:0,pending:0,failed:0});drawTable();message('已创建关联原任务的待执行演示任务。')});break}
 case 'confirm':{const fn=d.confirm;close(d);fn();break}
 }});
document.addEventListener('change',e=>{const el=e.target,d=el.closest('dialog');if(el.matches('[data-column]')){el.checked?displayFields.add(el.dataset.column):displayFields.delete(el.dataset.column);drawTable()}else if(el.id==='role'){role=el.value;selection.clear();render()}else if(el.id==='scene'){scene=el.value;render()}else if(el.matches('[data-check]')){el.checked?selection.add(Number(el.dataset.check)):selection.delete(Number(el.dataset.check));drawTable()}else if(el.id==='select-all'){filtered().slice((currentPage-1)*pageSize,currentPage*pageSize).forEach(r=>el.checked?selection.add(r.id):selection.delete(r.id));drawTable()}else if(el.id==='page-size'){pageSize=Number(el.value);currentPage=1;drawTable()}else if(el.matches('[data-result]')){$('[data-action="import"]',d).disabled=!d.querySelector('[data-result]:checked')}else if(el.id==='schedule-mode')drawSchedule(d);else if(el.id.startsWith('field-')||el.id.startsWith('op-')){syncRules(d);const bits=el.id.split('-'),c=editRules[Number(bits[1])].conditions[Number(bits[2])];if(bits[0]==='field'){c.op=c.field==='published_at'?'recent_days':'gte';c.value=1}else if(c.field==='published_at'&&['gte','lt'].includes(c.op))c.value='2026-11-01T00:00';drawRules(d)}});
$('#filters').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target),from=data.get('from'),to=data.get('to');if(from&&to&&from>to){$('#filter-error').hidden=false;$('#filter-error').textContent='发布时间的结束日期不能早于开始日期。';return}filters=Object.fromEntries(data);filters.category=data.getAll('category');selection.clear();currentPage=1;const expanded=$('.ex-filter-advanced',e.target)?.open;render();const advanced=$('#filters .ex-filter-advanced');if(advanced)advanced.open=expanded});
$('#filters').addEventListener('reset',()=>{queueMicrotask(()=>{filters={};selection.clear();currentPage=1;render()})});
window.addEventListener('hashchange',setPage);

function ruleSummary(rules){if(!rules.length)return '不自动转素材';return rules.map((r,i)=>`${i+1}. ${r.action==='filter'?'过滤':'命中'}：`+r.conditions.map(c=>c.op==='recent_days'?`发布时间 近 ${c.value} 天`:c.op==='recent_hours'?`发布时间 近 ${c.value} 小时`:`${({like_count:'点赞',favorite_count:'收藏',published_at:'发布时间'})[c.field]} ${({gte:'≥',lte:'≤',eq:'=',lt:'<',recent_days:'近 N 天',recent_hours:'近 N 小时'})[c.op]} ${c.value}`).join(r.logic==='all'?' 且 ':' 或 ')).join('；')}

window.addEventListener('resize',()=>$('#table').classList.toggle('has-overflow',$('#table').scrollWidth>$('#table').clientWidth+1));
